/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `media_album` (
  `id` varchar(16) NOT NULL COMMENT '相册 id（沿用原站 a001…a156）',
  `person_id` bigint DEFAULT NULL COMMENT '所属人物，关联 media_person.id',
  `title` varchar(300) NOT NULL COMMENT '相册标题（取自目录名/资料名）',
  `dir` varchar(600) NOT NULL COMMENT '相册物理目录（相对媒体根；同一目录可对应多本相册，如念念 144 套）',
  `photo_count` int NOT NULL DEFAULT '0' COMMENT '图片数量',
  `bytes` bigint NOT NULL DEFAULT '0' COMMENT '图片总字节数',
  `cover_path` varchar(500) DEFAULT NULL COMMENT '封面路径（相对站根，如 thumbs/p/a001/0000.jpg）',
  `note` varchar(1000) DEFAULT NULL COMMENT '备注',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序值，越小越靠前',
  `hidden` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否隐藏：0 显示 / 1 隐藏',
  `mtime` datetime DEFAULT NULL COMMENT '目录最后修改时间',
  `dir_key` varchar(600) DEFAULT NULL COMMENT '规范化相对目录（相册的稳定身份），空串表示根目录散图册',
  PRIMARY KEY (`id`),
  KEY `idx_album_dir` (`dir`(200)),
  KEY `idx_album_person` (`person_id`),
  KEY `idx_media_album_dir_key` (`dir_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='媒体-相册';
/*!40101 SET character_set_client = @saved_cs_client */;
